UPDATE workflows SET graph=$g${"nodes":[{"id":"start","type":"custom","data":{"variables":[{"variable":"user_id","label":"客户ID","description":"","type":"number","required":false,"hide":false,"max_length":null,"options":[]},{"variable":"customer_name","label":"客户称呼","description":"","type":"text-input","required":false,"hide":false,"max_length":48,"options":[]},{"variable":"history_hint","label":"上文摘要","description":"","type":"paragraph","required":false,"hide":false,"max_length":null,"options":[]}],"type":"start","title":"用户输入","desc":"","selected":false,"default_value":[{"key":"user_id","type":"number","value":1},{"key":"customer_name","type":"string","value":"陈女士"},{"key":"history_hint","type":"string","value":""}]},"position":{"x":40,"y":420},"positionAbsolute":{"x":40,"y":420},"targetPosition":"left","sourcePosition":"right","width":242,"height":100,"selected":false},{"id":"prepare","type":"custom","data":{"type":"template-transform","title":"拼接上下文","desc":"","variables":[{"variable":"history_hint","value_selector":["start","history_hint"]},{"variable":"query","value_selector":["sys","query"]}],"template":"{% if history_hint %}[上文] {{ history_hint }}\n[当前问题] {{ query }}{% else %}{{ query }}{% endif %}","selected":false},"position":{"x":280,"y":420},"positionAbsolute":{"x":280,"y":420},"targetPosition":"left","sourcePosition":"right","width":242,"height":100,"selected":false},{"id":"classifier","type":"custom","data":{"type":"question-classifier","title":"意图分类","desc":"","query_variable_selector":["prepare","output"],"model":{"provider":"langgenius/tongyi/tongyi","name":"qwen3.8-flash","mode":"chat","completion_params":{"temperature":0.0,"max_tokens":800,"enable_thinking":false}},"classes":[{"id":"c_recommend","name":"留学项目推荐：描述年龄、学历、预算、意向，希望匹配适合的留学项目，例如「19岁高中刚毕业想快点拿本科学历」。只表达意向但没说条件的（例如「想出国」「我想留学」「不知道读什么」）也归这一类"},{"id":"c_project_query","name":"项目或课程查询：问有哪些项目、某个项目读几年、学什么课程、包含哪些服务、适合什么人，例如「德国双元制项目是什么」「0.5+1 要读几年」"},{"id":"c_event_query","name":"活动查询：问最近有什么讲座、分享会、说明会，某场活动还有没有名额、已经有哪些人报名（名单），例如「这周有什么活动」「新加坡分享会还有名额吗」「这场活动都谁报名了」"},{"id":"c_event_register","name":"活动报名：客户**自己**要报名某场活动（讲座/分享会/说明会/沙龙），主语是「我」要参加，例如「我要报名新加坡留学分享会」「帮我报个名」。注意：问「谁报名了」「有哪些人报名」是查名单，不属于这里；报名某个留学项目属于项目咨询"},{"id":"c_leave_contact","name":"留资登记：客户报出自己的姓名、手机号、微信，希望顾问联系他，例如「我叫陈晨，电话13800138000，帮我安排老师联系」"},{"id":"c_child_query","name":"家长查孩子：家长问自己孩子的成绩、考得怎么样、请假批了没、报了什么活动，例如「我孩子这次考了多少分」「孩子请假通过了吗」。注意：问留学项目、费用、活动报名不属于这一类"},{"id":"c_faq","name":"公司与政策咨询：学费多少钱、费用与预算、申请条件、入学要求、留学政策、签证与材料清单、公司介绍、某个项目怎么申请怎么报名，以及不属于上面任何一类的问题"}],"instruction":"","instructions":"","vision":{"enabled":false},"selected":false},"position":{"x":520,"y":200},"positionAbsolute":{"x":520,"y":200},"targetPosition":"left","sourcePosition":"right","width":242,"height":100,"selected":false},{"id":"recommend_http","type":"custom","data":{"type":"http-request","title":"画像研判推荐","desc":"","method":"post","url":"http://host.docker.internal:8000/api/agent/profile-evaluate","authorization":{"type":"no-auth","config":null},"headers":"Content-Type:application/json\nX-Internal-Token:yj-internal-demo-2026","params":"","body":{"type":"json","data":[{"key":"","type":"text","value":"{\"raw_text\":\"{{#sys.query#}}\"}"}]},"timeout":{"connect":10,"read":30,"write":10},"retry_config":{"retry_enabled":true,"max_retries":2,"retry_interval":500},"ssl_verify":true,"variables":[],"selected":false},"position":{"x":860,"y":40},"positionAbsolute":{"x":860,"y":40},"targetPosition":"left","sourcePosition":"right","width":242,"height":100,"selected":false},{"id":"recommend_llm","type":"custom","data":{"type":"llm","title":"推荐话术","desc":"","model":{"provider":"langgenius/tongyi/tongyi","name":"qwen3.8-flash","mode":"chat","completion_params":{"temperature":0.3,"max_tokens":2000,"enable_thinking":false}},"prompt_template":[{"role":"system","text":"你是「粤教服务」的售前顾问，服务对象是想出国留学的学生和家长，负责项目推荐、课程查询、活动报名和公司政策咨询。\n客户正在咨询该读什么项目，你要基于规则引擎的匹配结果做推荐。\n【铁律】\n1. 业务数据只能来自「工具返回」里的 data 字段，不许自己编造姓名、时间、分数、单号、名额。\n2. 工具返回 code 不为 0，或出现 detail / msg 里带\"未找到\"\"不存在\"\"已满\"\"非法\"\"没有权限\"等字眼时，如实转述原因，并给出一个下一步建议；不要把失败说成成功。\n3. 用中文口语回答，不要输出 JSON、不要暴露接口路径、不要提\"工具\"\"节点\"\"API\"这些词。\n4. 回答控制在 6 句话以内，需要罗列信息时用简短列表。\n5. 学生端输入若以上文形式给出（[上文] … [当前问题] …），只回答\"当前问题\"，绝不要复述[上文]里的内容。\n6. 推荐要有主次：先说出最推荐项目的全名和匹配度分值，再给 2 条推荐理由；然后从工具返回的 matches 里再挑 1~2 个备选项目，各附匹配度分值和一句话理由（例如「备选：××班，匹配度 85 分，理由……」），让客户有的选。备选的项目名和分值同样只能来自工具返回，matches 里没有的项目不许提。matches 里只有主推一个时，就只说主推，不要提「没有备选」「工具返回」这类词。\n7. 如果 matches 为空（用户没说年龄或学历），本次回答**只做一件事：追问**。第一句就必须是问题，问最高学历（在读还是已毕业）和年龄。\n   整段回答里禁止出现任何国家名、项目名、费用数字，禁止列「你可以考虑 A/B/C 几个方向」这类清单。\n   最多补一句「不同学历对应的路径差别很大」，然后立刻提问。\n8. 不要承诺录取结果、不要报出资料里没有的费用数字。\n9. 结尾必须问一句：方便留个姓名和手机号吗，我让顾问老师把项目资料发给你（引导留资）。\n","id":"5f9c6d85-ad16-4782-bbb9-86f334794573"},{"role":"user","text":"客户说：{{#sys.query#}}\n\n工具返回：{{#recommend_http.body#}}\n\n请先复述你从他的话里读到的画像（年龄、学历、意向），再按「主推 + 备选」推荐：主推荐给出全名、匹配度和 2 条理由，之后附 1~2 个备选项目及各自匹配度和一句话理由，让客户有的选。","id":"f17fc3c2-f0a0-4e84-aa9a-5691c287adaf"}],"context":{"enabled":false,"variable_selector":[]},"vision":{"enabled":false},"memory":{"role_prefix":{"user":"用户","assistant":"助手"},"window":{"enabled":true,"size":4},"query_prompt_template":null},"reasoning_format":"separated","selected":false},"position":{"x":1180,"y":40},"positionAbsolute":{"x":1180,"y":40},"targetPosition":"left","sourcePosition":"right","width":242,"height":100,"selected":false},{"id":"recommend_ans","type":"custom","data":{"type":"answer","title":"推荐回复","desc":"","answer":"{{#recommend_llm.text#}}","variables":[],"selected":false},"position":{"x":1500,"y":40},"positionAbsolute":{"x":1500,"y":40},"targetPosition":"left","sourcePosition":"right","width":242,"height":100,"selected":false},{"id":"project_http","type":"custom","data":{"type":"http-request","title":"项目列表查询","desc":"","method":"get","url":"http://host.docker.internal:8000/api/agent/project-list","authorization":{"type":"no-auth","config":null},"headers":"Content-Type:application/json\nX-Internal-Token:yj-internal-demo-2026","params":"","body":{"type":"none","data":[]},"timeout":{"connect":10,"read":30,"write":10},"retry_config":{"retry_enabled":true,"max_retries":2,"retry_interval":500},"ssl_verify":true,"variables":[],"selected":false},"position":{"x":860,"y":270},"positionAbsolute":{"x":860,"y":270},"targetPosition":"left","sourcePosition":"right","width":242,"height":100,"selected":false},{"id":"project_llm","type":"custom","data":{"type":"llm","title":"项目介绍","desc":"","model":{"provider":"langgenius/tongyi/tongyi","name":"qwen3.8-flash","mode":"chat","completion_params":{"temperature":0.3,"max_tokens":2000,"enable_thinking":false}},"prompt_template":[{"role":"system","text":"你是「粤教服务」的售前顾问，服务对象是想出国留学的学生和家长，负责项目推荐、课程查询、活动报名和公司政策咨询。\n客户想了解具体项目，你要从项目清单里挑出相关的介绍。\n【铁律】\n1. 业务数据只能来自「工具返回」里的 data 字段，不许自己编造姓名、时间、分数、单号、名额。\n2. 工具返回 code 不为 0，或出现 detail / msg 里带\"未找到\"\"不存在\"\"已满\"\"非法\"\"没有权限\"等字眼时，如实转述原因，并给出一个下一步建议；不要把失败说成成功。\n3. 用中文口语回答，不要输出 JSON、不要暴露接口路径、不要提\"工具\"\"节点\"\"API\"这些词。\n4. 回答控制在 4 句话以内，需要罗列信息时用简短列表。\n5. 学生端输入若以上文形式给出（[上文] … [当前问题] …），只回答\"当前问题\"，绝不要复述[上文]里的内容。\n6. 如果[上文]提到过某个项目而当前问题只是「学费多少/读几年/怎么报名」，就按那个项目回答，不要换成别的国家。\n","id":"308de59c-ddba-4784-83e9-4ed52c68e40b"},{"role":"user","text":"客户问：{{#sys.query#}}\n\n上文：{{#start.history_hint#}}\n\n工具返回：{{#project_http.body#}}\n\n请只讲和他问题相关的项目（项目名、适合人群、学制、特点），不要把所有项目都念一遍；项目清单里没有费用数字就说「费用让顾问老师给你准确报价」。","id":"12792f27-8216-4447-ab69-649f11f6bca9"}],"context":{"enabled":false,"variable_selector":[]},"vision":{"enabled":false},"memory":{"role_prefix":{"user":"用户","assistant":"助手"},"window":{"enabled":true,"size":4},"query_prompt_template":null},"reasoning_format":"separated","selected":false},"position":{"x":1180,"y":270},"positionAbsolute":{"x":1180,"y":270},"targetPosition":"left","sourcePosition":"right","width":242,"height":100,"selected":false},{"id":"project_ans","type":"custom","data":{"type":"answer","title":"项目回复","desc":"","answer":"{{#project_llm.text#}}","variables":[],"selected":false},"position":{"x":1500,"y":270},"positionAbsolute":{"x":1500,"y":270},"targetPosition":"left","source