:"separated","selected":false},"position":{"x":1180,"y":500},"positionAbsolute":{"x":1180,"y":500},"targetPosition":"left","sourcePosition":"right","width":242,"height":100,"selected":false},{"id":"event_ans","type":"custom","data":{"type":"answer","title":"活动回复","desc":"","answer":"{{#event_llm.text#}}","variables":[],"selected":false},"position":{"x":1500,"y":500},"positionAbsolute":{"x":1500,"y":500},"targetPosition":"left","sourcePosition":"right","width":242,"height":100,"selected":false},{"id":"register_extract","type":"custom","data":{"type":"llm","title":"抽取报名信息","desc":"","model":{"provider":"langgenius/tongyi/tongyi","name":"qwen3.8-flash","mode":"chat","completion_params":{"temperature":0.3,"max_tokens":2000,"enable_thinking":false}},"prompt_template":[{"role":"system","text":"你是一个信息抽取器。提取客户想报名的活动名称，只输出 JSON，不要解释、不要代码块。\nowner_employee_id 固定填 3（由李老师接手）。\n输出格式：{\"event_name\":\"活动名称\",\"customer_id\":\"{{#start.user_id#}}\"}","id":"ef967e6a-51e0-43f2-8897-580bd941aecf"},{"role":"user","text":"客户说：{{#sys.query#}}","id":"97f8dd1b-831a-4b09-990b-50443efeaa52"}],"context":{"enabled":false,"variable_selector":[]},"vision":{"enabled":false},"memory":null,"reasoning_format":"separated","selected":false},"position":{"x":860,"y":730},"positionAbsolute":{"x":860,"y":730},"targetPosition":"left","sourcePosition":"right","width":242,"height":100,"selected":false},{"id":"register_http","type":"custom","data":{"type":"http-request","title":"活动报名","desc":"","method":"post","url":"http://host.docker.internal:8000/api/agent/event-register?soft_fail=1","authorization":{"type":"no-auth","config":null},"headers":"Content-Type:application/json\nX-Internal-Token:yj-internal-demo-2026","params":"","body":{"type":"json","data":[{"key":"","type":"text","value":"{{#register_extract.text#}}"}]},"timeout":{"connect":10,"read":30,"write":10},"retry_config":{"retry_enabled":true,"max_retries":2,"retry_interval":500},"ssl_verify":true,"variables":[],"selected":false,"error_strategy":"default-value","default_value":[{"key":"body","type":"string","value":"{\"code\": -1, \"msg\": \"报名接口暂时不可用（网络或服务异常），请稍后再试一次。\"}"},{"key":"status_code","type":"number","value":400}]},"position":{"x":1180,"y":730},"positionAbsolute":{"x":1180,"y":730},"targetPosition":"left","sourcePosition":"right","width":242,"height":100,"selected":false},{"id":"register_llm","type":"custom","data":{"type":"llm","title":"报名回执","desc":"","model":{"provider":"langgenius/tongyi/tongyi","name":"qwen3.8-flash","mode":"chat","completion_params":{"temperature":0.3,"max_tokens":2000,"enable_thinking":false}},"prompt_template":[{"role":"system","text":"你是「粤教服务」的售前顾问，服务对象是想出国留学的学生和家长，负责项目推荐、课程查询、活动报名和公司政策咨询。\n客户刚报名了活动，你要给回执。\n【铁律】\n1. 业务数据只能来自「工具返回」里的 data 字段，不许自己编造姓名、时间、分数、单号、名额。\n2. 工具返回 code 不为 0，或出现 detail / msg 里带\"未找到\"\"不存在\"\"已满\"\"非法\"\"没有权限\"等字眼时，如实转述原因，并给出一个下一步建议；不要把失败说成成功。\n3. 用中文口语回答，不要输出 JSON、不要暴露接口路径、不要提\"工具\"\"节点\"\"API\"这些词。\n4. 回答控制在 4 句话以内，需要罗列信息时用简短列表。\n5. 学生端输入若以上文形式给出（[上文] … [当前问题] …），只回答\"当前问题\"，绝不要复述[上文]里的内容。\n6. 先看工具返回的 data.success：\n   - true（或返回里没有 success 字段且 msg 含「报名成功」）：确认活动名称、时间、地点，说明名额已占用。\n   - false：说明 msg 里的真实原因，**原样引用活动名和人数**（例如「名额已满（30/30）」）。禁止写「可能是名额已满」「请核对活动名称」这类猜测措辞，因为你已经知道确切原因了。\n7. 如果 data.duplicated 为 true，告诉他之前已经报过这一场，不用重复提交，回执号保持不变。\n","id":"2a0ef0f3-0a3e-4c31-8b0d-cba2ca526b39"},{"role":"user","text":"客户说：{{#sys.query#}}\n\n工具返回：{{#register_http.body#}}\n\n请按 data.success 和 msg 如实给回执。","id":"f14e33d8-341f-4c5a-bcfd-1174e3045503"}],"context":{"enabled":false,"variable_selector":[]},"vision":{"enabled":false},"memory":null,"reasoning_format":"separated","selected":false},"position":{"x":1500,"y":730},"positionAbsolute":{"x":1500,"y":730},"targetPosition":"left","sourcePosition":"right","width":242,"height":100,"selected":false},{"id":"register_ans","type":"custom","data":{"type":"answer","title":"报名回复","desc":"","answer":"{{#register_llm.text#}}","variables":[],"selected":false},"position":{"x":1820,"y":730},"positionAbsolute":{"x":1820,"y":730},"ta