ry_interval":500},"ssl_verify":true,"variables":[],"selected":false,"error_strategy":"default-value","default_value":[{"key":"body","type":"string","value":"{\"code\": -1, \"msg\": \"这个账号没有绑定学生档案，可能不是家长账号；请说明只有家长账号能查孩子信息。\"}"},{"key":"status_code","type":"number","value":400}]},"position":{"x":860,"y":1190},"positionAbsolute":{"x":860,"y":1190},"targetPosition":"left","sourcePosition":"right","width":242,"height":100,"selected":false},{"id":"child_llm","type":"custom","data":{"type":"llm","title":"家长播报","desc":"","model":{"provider":"langgenius/tongyi/tongyi","name":"qwen3.8-flash","mode":"chat","completion_params":{"temperature":0.3,"max_tokens":2000,"enable_thinking":false}},"prompt_template":[{"role":"system","text":"你是「粤教服务」的售前顾问，服务对象是想出国留学的学生和家长，负责项目推荐、课程查询、活动报名和公司政策咨询。\n对方是学生家长，问的是自己孩子的情况。\n【铁律】\n1. 业务数据只能来自「工具返回」里的 data 字段，不许自己编造姓名、时间、分数、单号、名额。\n2. 工具返回 code 不为 0，或出现 detail / msg 里带\"未找到\"\"不存在\"\"已满\"\"非法\"\"没有权限\"等字眼时，如实转述原因，并给出一个下一步建议；不要把失败说成成功。\n3. 用中文口语回答，不要输出 JSON、不要暴露接口路径、不要提\"工具\"\"节点\"\"API\"这些词。\n4. 回答控制在 4 句话以内，需要罗列信息时用简短列表。\n5. 学生端输入若以上文形式给出（[上文] … [当前问题] …），只回答\"当前问题\"，绝不要复述[上文]里的内容。\n6. 只讲 data 里这位孩子的情况，不要提到别的学生。\n7. 问成绩就给各科分数和平均分（平均分不含雅思/托福）；问请假就说最近一次的状态和审批人；问活动就说报名了哪一场。\n8. 如果 data.bound 为 false，说明这个账号还没绑定学生，请家长联系教务老师。\n","id":"1bcff071-d340-4f13-875a-f5605d1dff4a"},{"role":"user","text":"家长问：{{#sys.query#}}\n\n工具返回：{{#child_http.body#}}\n\n请用家长能听懂的话回答。","id":"7bb1967a-2cbf-492c-b87e-cf099e90f416"}],"context":{"enabled":false,"variable_selector":[]},"vision":{"enabled":false},"memory":null,"reasoning_format":"separated","selected":false},"position":{"x":1500,"y":1190},"positionAbsolute":{"x":1500,"y":1190},"targetPosition":"left","sourcePosition":"right","width":242,"height":100,"selected":false},{"id":"child_ans","type":"custom","data":{"type":"answer","title":"家长回复","desc":"","answer":"{{#child_llm.text#}}","variables":[],"selected":false},"position":{"x":1820,"y":1190},"positionAbsolute":{"x":1820,"y":1190},"targetPosition":"left","sourcePosition":"right","width":242,"height":100,"selected":false},{"id":"faq_kb","type":"custom","data":{"type":"knowledge-retrieval","title":"知识检索","desc":"","query_variable_selector":["sys","query"],"dataset_ids":["ef37795b-f4f8-47da-933f-739942b47692"],"retrieval_mode":"multiple","multiple_retrieval_config":{"top_k":10,"score_threshold":0.3,"score_threshold_enabled":true,"reranking_mode":"reranking_model","reranking_enable":false,"reranking_model":{"provider":"langgenius/tongyi/tongyi","model":"qwen3-vl-rerank"}},"selected":false},"position":{"x":860,"y":1420},"positionAbsolute":{"x":860,"y":1420},"targetPosition":"left","sourcePosition":"right","width":242,"height":100,"selected":false},{"id":"faq_llm","type":"custom","data":{"type":"llm","title":"政策问答","desc":"","model":{"provider":"langgenius/tongyi/tongyi","name":"qwen3.8-flash","mode":"chat","completion_params":{"temperature":0.3,"max_tokens":2000,"enable_thinking":false}},"prompt_template":[{"role":"system","text":"你是「粤教服务」的咨询顾问，回答公司介绍、留学政策、费用标准、签证材料、申请流程等问题。\n只依据下面检索到的资料回答。涉及学费、学制、分数、时间、政策条款时，照抄资料里的数字和表述，不许自己算、不许编。\n资料没覆盖的，直接说「这个我需要让顾问老师跟你确认」。\n第一句先直接回答客户问的那件事，再补充相关细节，不要跑题去介绍别的项目。\n如果[上文]提到过某个项目或国家，而当前问题很简短（例如「学费多少」「怎么报名」），就沿用上文那个项目回答。\n客户问申请条件、政策、材料、费用时，按资料里的条款直接答，不要用某个项目班的招生介绍来代替。\n资料里同时给了「培训津贴」和「毕业后薪资」时，两个都要说：培训期间是津贴（例如第一年 880 欧/月、第二年 950、第三年 1030），毕业后才是工资（例如 2100-3500 欧/月），要把两者区分开，不要只挑一个。\n如果客户只说了「想出国」「想留学」这类没有具体对象的诉求，不要罗列国家清单、不要报费用，先用一句话问清最高学历（在读还是已毕业）和年龄。\n回答用中文，控制在 6 句话以内，信息多就分条列。","id":"6b8b8b92-5ed7-4760-9b62-c57c0b3193f7"},{"role":"user","text":"客户问：{{#sys.query#}}\n\n上文：{{#start.history_hint#}}\n\n参考资料：{{#context#}}","id":"a88e8d0e-1c44-4a25-9e88-3a1d2da5c70a"}],"context":{"enabled":true,"variable_selector":["faq_kb","result"]},"vision":{"enabled":false},"memory":{"role_prefix":{"user":"用户","assistant":"助手"},"window":{"enabled":true,"size":4},"query_prompt_template":null},"reasoning_format":"separated","selected":false},"position":{"x":1180,"y":1420},"positionAbsolute":{"x":1180,"y":1420},"targetPositi